void on_tree_collapse_all() { g_tree->collapseAll(); show_tree(); }
void on_tree_toggle_src() { g_tree->toggle(N_SRC); show_tree(); }
void on_tree_collapse_core() { g_tree->collapse(N_CORE); show_tree(); }
